      return { rels: rs, act: orAll(rs.map(r => (C.activate[r.type] ?? 0.3) * C.activateGain)), tension: only(C.tension), bond: only(C.bond), clash, harm, complete: rs.some(r => r.type === '삼합' || r.type === '방합') ? 1 : 0 };
