    const stemRel = F.stemHap ? 0.8 : F.stemClash ? 0.5 : 0;
    const star = Math.min(1, (F.g[2] + F.g[3]) / A.starNorm), expr = dRamp(F.g[1]);
    const charm = Math.min(1, (F.sinNames.includes('홍염살') ? Q.charm.hongyeom : 0) + (F.dohwa ? Q.charm.dohwa : 0) + (F.sinNames.includes('천을귀인') ? Q.charm.cheoneul : 0));
