    sp.rels.forEach(r => pushR(why, 30 * (DOMAIN_COMMON.activate[r.type] ?? 0.3), `배우자궁(일지) ${relText(r)} — ${DOMAIN_COMMON.bond[r.type] != null ? '결속' : '긴장'} 신호로 관계 활동이 움직입니다`));
    if (F.stemHap) pushR(why, 22, '일간과 운 천간이 합 — 관계 연결 신호'); if (F.stemClash) pushR(why, 18, '일간과 운 천간이 충 — 관계에서 주도권 자극');
