    const r0 = dRamp(F.g[0]), r1 = dRamp(F.g[1]), r2 = dRamp(F.g[2]), r3 = dRamp(F.g[3]), r4 = dRamp(F.g[4]), link = Math.sqrt(r1 * r2), mo = F.month;
