    if (F.filled.length) pushR(why, 14, `부족한 ${F.filled.map(e => EL_K[e]).join('·')} 오행을 채워 줍니다`);
    if (F.ovLevel > 0.25) pushR(why, 26 * F.ovLevel, `${EL_K[F.ovEl]} 기운이 중첩되어 편중이 심해집니다(부담 증가)`);
