    if (L1 > 25) pushR(why, L1 / 3, `${F.help > 50 ? '이미 강한 원국' : '이미 약한 원국'}을 ${F.help > 50 ? '더 강하게' : '더 소모시키는'} 기운(${Math.round(ex * 100)}%)이 들어와 부담이 커집니다`);
    if (tension > 25) pushR(why, tension / 4, `합충형파해 긴장 ${Math.round(tension)} 누적 — 부담도에 반영`);
    if (L3 > 0) pushR(why, L3 / 8, `변동성 ${Math.round(vol)}가 매우 높아 부담도에 일부 반영됩니다(변동성만으로 크게 낮추지 않음)`);
    if (L4 > 20) pushR(why, L4 / 4, `원국 적합도가 낮아(흐름 점수 ${Math.round(F.fit)}) 부담이 커집니다`);
    if (dRamp(F.g[4]) > 0.35) pushR(why, 12, '인성 기운이 들어와 회복·보호 신호가 늘어납니다(참고)');
