  function scoreAccident(c) {
    const Q = ACCIDENT_CONFIG, W = Q.weights, base = W.volatility * c.volatility + W.conflict * c.conflict + W.overload * c.overload + W.instability * c.instability + W.sinsal * c.sinsal;
    const nHigh = [c.volatility, c.conflict, c.overload, c.instability].filter(v => v >= Q.synergy.from).length;
    const mult = nHigh >= 2 ? 1 + Q.synergy.gain * (nHigh - 1) : nHigh === 1 ? Q.synergy.solo : Q.synergy.none;
    return { score: lclamp(base * mult, 0, 100), base, mult, nHigh };
  }

  // ── 태그·요약 (성분 조합으로 정하며, 성분이 서로 달라 같은 숫자를 복사하지 않는다)
  function tagsLove(c, F) {
    const T = LOVE_CONFIG.tags, out = [];
    if (c.activity >= T.active) out.push('만남활성');
    if (c.activity >= T.develop && c.fit >= T.fit && (F.spouse.bond > 0.3 || F.stemHap || F.bond > 30)) out.push('관계발전');
    if (c.stability >= T.stable && c.fit >= T.fitStable) out.push('관계안정');
    if (c.volatility >= T.vol) out.push('관계변동');
    if (c.activity < T.quiet && c.stability >= T.quietStable) out.push('내실기');
    return out.slice(0, 3);
  }
  function summaryLove(c) {
    const T = LOVE_CONFIG.tags, hiA = c.activity >= T.active, hiS = c.stability >= T.stable, hiV = c.volatility >= T.vol;
    if (hiA && hiV) return '관계 활동이 활발하지만 변동도 큰 시기입니다.';
    if (hiA && !hiS) return '관계 활동은 활발하지만 안정성은 낮은 시기입니다.';
    if (hiA && hiS) return '관계 활동이 활발하고 안정성도 받쳐 주는 시기입니다.';
    if (c.activity < T.quiet && hiS) return '관계 활동은 조용하고 안정적으로 다지는 시기입니다.';
    if (hiV) return '관계 환경의 변동 신호가 큰 시기입니다.';
    return '관계 영역에 뚜렷한 쏠림이 없는 무난한 시기입니다.';
  }
  function tagsWealth(c, a) {
    const T = WEALTH_CONFIG.tags, out = [];
    if (c.activity >= T.earn && (a.r2 >= 0.3 || a.link >= 0.3)) out.push('수입활성');
    if (a.r2 >= T.harvest && c.fit >= T.harvestFit) out.push('성과회수');
    if (a.r1 >= T.bizProduce && a.r0 >= T.bizPeers && c.activity >= T.biz) out.push('사업활성');
    if (c.stability >= T.stable && c.fit >= T.fitStable) out.push('재정안정');
    if (c.volatility >= T.vol) out.push('재정변동');
    if (c.fit < T.spend && c.activity >= T.spendActivity) out.push('지출관리');
    if (a.r4 >= T.base && c.activity < T.baseActivity) out.push('기반축적');
    return out.slice(0, 3);
  }
  function summaryWealth(c) {
    const hiA = c.activity >= 65, loF = c.fit < 50, loS = c.stability < 50, hiV = c.volatility >= 65;
    if (hiA && (loF || loS) && hiV) return '재정 활동은 매우 활발하지만 변동과 부담도 큰 시기입니다.';
    if (hiA && loF) return '돈의 움직임은 활발하지만 재정적으로 유리한 구조는 아닙니다.';
    if (hiA && c.fit >= 55 && c.stability >= 55) return '재정 활동이 활발하고 재정적으로도 유리한 시기입니다.';
    if (hiA) return '돈의 움직임이 활발한 시기입니다. 유리한지는 적합도와 안정성을 함께 보세요.';
    if (c.activity < 40 && c.stability >= 60) return '재정 활동은 잠잠하지만 안정적으로 지키기 좋은 시기입니다.';
    if (hiV) return '재정 환경의 변동 신호가 큰 시기입니다.';
    return '재정 영역에 뚜렷한 쏠림이 없는 무난한 시기입니다.';
  }
  function summaryHealth(c) {
    if (c.load >= 60) return '균형·부담 면에서 관리가 필요한 시기입니다.';
    if (c.balance >= 65 && c.climate >= 60) return '오행 균형과 조후 균형이 대체로 안정적인 시기입니다.';
    if (c.recovery >= 65) return '회복·보호 신호가 받쳐 주는 시기입니다.';
    return '균형·부담 면에서 무난한 시기입니다.';
  }
  function summaryAccident(sc) {
    if (sc.nHigh >= 3) return '여러 주의 신호가 동시에 중첩된 시기입니다. 일정·체력·주변 환경을 여유 있게 점검하세요.';
    if (sc.nHigh === 2) return '두 가지 이상의 주의 신호가 겹칩니다. 서두르거나 무리하는 일정은 줄이는 편이 좋습니다.';
    if (sc.nHigh === 1) return '한 가지 신호만 두드러져 전체 주의도는 제한적입니다.';
    return '주의 신호가 두드러지지 않는 시기입니다.';
  }

  // ── 시간 단위별 상위 운(대운→세운→월운→일진) 찾기
  function domainAncestors(ch, level, context) {
    const P = context.parents || {}, ms = context.ms, out = [];
    const need = { seun: ['daeun'], wolun: ['daeun', 'seun'], ilun: ['daeun', 'seun', 'wolun'] }[level] || [];
    for (const a of need) {
      let p = P[a];
      if (!p && ms != null) p = a === 'daeun' ? daeunAt(ch, ms) : a === 'seun' ? yearPillarAt(ms) : monthPillarAt(ms);
      if (p) out.push({ level: a, p });
    }
    return out;
  }
  function domainOwn(ch, p, level) {
    const F = extractLuckFeatures(ch, p, level), k = DOMAIN_LEVEL_WEIGHTS[level].emphasis;
    let m = _dmO.get(ch); if (!m) _dmO.set(ch, m = {});
    const ck = level + ':' + F.pillar.i;
    if (m[ck]) return m[ck];
    const health = evaluateHealth(F, k);
    return m[ck] = { F, love: evaluateLove(F, k), wealth: evaluateWealth(F, k), health, accident: evaluateAccident(F, k, health.aux) };
  }
  const blendComps = (list, key) => {
    const out = {}; let tw = 0; list.forEach(x => { tw += x.w; });
    for (const c of Object.keys(list[list.length - 1].own[key].comps)) out[c] = list.reduce((s, x) => s + x.w * x.own[key].comps[c], 0) / tw;
    return out;
  };
  // 같은 엔진으로 네 지수를 한꺼번에 계산. level: daeun·seun·wolun·ilun(=iljin), context.ms: 그 운 기간 안의 시각(상위 운을 찾는 데 씀)
  function evaluateDomainLuck(ch, p, level = 'seun', context = {}) {
    const lv = level === 'iljin' ? 'ilun' : level, W = DOMAIN_LEVEL_WEIGHTS[lv];
    if (!W) throw new Error('level: ' + level);
    const anc = domainAncestors(ch, lv, context);
    const list = [...anc.map(a => ({ level: a.level, p: a.p, w: W.chain[a.level] ?? 0 })), { level: lv, p, w: W.self }].filter(x => x.w > 0).map(x => ({ ...x, own: domainOwn(ch, x.p, x.level) }));
    const tw = list.reduce((s, x) => s + x.w, 0), self = list[list.length - 1], chainNote = list.length > 1 ? `상위 운 반영: ${list.slice(0, -1).map(x => `${x.level === 'daeun' ? '대운' : x.level === 'seun' ? '세운' : '월운'} ${gzName(x.p)} ${Math.round(x.w / tw * 100)}%`).join(' · ')} · 이 운 자체 ${Math.round(self.w / tw * 100)}%` : '';
    const res = { level: lv, chain: list.map(x => ({ level: x.level, ganzhi: gzName(x.p), weight: x.w / tw })), chainNote };
    // 애정
    let c = blendComps(list, 'love'); let score = Math.round(scoreLove(c));
    res.love = { key: 'love', score, band: domainBand('love', score), components: c, tags: tagsLove(c, self.own.F), summary: summaryLove(c), reasons: self.own.love.reasons,
      parts: [{ key: 'activity', label: '관계 활성도', v: c.activity, w: LOVE_CONFIG.score.activity }, { key: 'fit', label: '원국 적합도', v: c.fit, w: LOVE_CONFIG.score.fit }, { key: 'stability', label: '관계 안정성', v: c.stability, w: LOVE_CONFIG.score.stability }, { key: 'volatility', label: '관계 변동성(점수 미반영·참고)', v: c.volatility, w: 0 }] };
    // 재물
    c = blendComps(list, 'wealth'); score = Math.round(scoreWealth(c));
    res.wealth = { key: 'wealth', score, band: domainBand('wealth', score), components: c, tags: tagsWealth(c, self.own.wealth.aux), summary: summaryWealth(c), reasons: self.own.wealth.reasons,
      parts: [{ key: 'activity', label: '재정 활동성', v: c.activity, w: WEALTH_CONFIG.score.activity }, { key: 'fit', label: '재정 적합도', v: c.fit, w: WEALTH_CONFIG.score.fit }, { key: 'stability', label: '재정 안정성', v: c.stability, w: WEALTH_CONFIG.score.stability }, { key: 'volatility', label: '재정 변동성(점수 미반영·참고)', v: c.volatility, w: 0 }] };
    // 건강
    c = blendComps(list, 'health'); score = Math.round(scoreHealth(c));
    res.health = { key: 'health', score, band: domainBand('health', score), components: c, tags: [], summary: summaryHealth(c), reasons: self.own.health.reasons,
      parts: [{ key: 'balance', label: '오행 균형', v: c.balance, w: HEALTH_CONFIG.score.balance }, { key: 'climate', label: '조후 균형', v: c.climate, w: HEALTH_CONFIG.score.climate }, { key: 'load', label: '부담도(낮을수록 좋음)', v: c.load, w: HEALTH_CONFIG.score.load, inverse: true }, { key: 'recovery', label: '회복 신호', v: c.recovery, w: HEALTH_CONFIG.score.recovery }, { key: 'volatility', label: '변동성(부담도에 일부 반영)', v: c.volatility, w: 0 }] };
    // 사고수
    c = blendComps(list, 'accident'); const sc = scoreAccident(c); score = Math.round(sc.score);
    const accW = ACCIDENT_CONFIG.weights;
    res.accident = { key: 'accident', score, cautionIndex: score, accidentRiskIndex: score, band: domainBand('accident', score), components: c, tags: [], summary: summaryAccident(sc), reasons: self.own.accident.reasons, synergy: { nHigh: sc.nHigh, mult: sc.mult, base: sc.base },
      parts: [{ key: 'volatility', label: '변동성', v: c.volatility, w: accW.volatility }, { key: 'conflict', label: '충돌 신호', v: c.conflict, w: accW.conflict }, { key: 'overload', label: '과부하', v: c.overload, w: accW.overload }, { key: 'instability', label: '구조 불안정', v: c.instability, w: accW.instability }, { key: 'sinsal', label: '신살 참고', v: c.sinsal, w: accW.sinsal }] };
    return res;
  }

