    const seasonalSupport = { deukryeong: st.deukryeong, deukji: st.deukji, deukse: st.deukse, help: st.help, zone: st.zone, note: '득령은 월지 본기가 일간을 돕는지(비겁·인성 포함)를 보는 계절 지원이고, 통근은 같은 오행의 뿌리가 지장간에 있는지를 봅니다. 통근이 강해도 신강으로, 무근이라고 신약으로 자동 판정하지 않습니다.' };
    r = { dayMaster: STEM[d], dayMasterK: STEM_K[d], dayElement: dEl, hasNatalRoot, natalRootScore, natalRootLevel: rootLevelLabel(natalRootScore), roots, strongestRoot, pillarShare, rawContribution: raw, reasons, seasonalSupport };
