    const fit = rootFitEffect(ch, change, fitLevel);
    const changes = provided.map(l => ({ level: l.level, levelName: ROOT_LEVEL_NAME[l.level], branch: l.sup.branch, kind: l.sup.kind, score: l.sup.supportScore, text: `${ROOT_LEVEL_NAME[l.level]} ${l.sup.branch} — ${l.sup.kind} 유입` }));
    const pieces = [nat.hasNatalRoot ? `원국 ${nat.natalRootLevel}` : '원국 무근'];
    pieces.push(change >= 5 ? '운에서 근 보강' : (nat.hasNatalRoot ? '추가되는 근 없음' : '운에서도 근 보강 없음'));
