    const levelNames = provided.map(l => ROOT_LEVEL_NAME[l.level]).join('·');
    const reasons = [];
    if (provided.length >= 2) reasons.push(`${levelNames}에서 근이 겹쳐 들어와 현재 일간의 기반이 보강되는 흐름입니다`);
    else if (provided.length === 1) reasons.push(`${levelNames}에서 일간을 지지하는 근이 들어옵니다`);
    if (nat.natalRootScore > 0 && !provided.length) reasons.push('운에서 추가되는 근이 없어도 원국의 통근은 그대로 유지됩니다(감점하지 않음)');
