  const TAEK_REL = { '충': -18, '형': -8, '해': -5, '파': -4, '원진': -5, '육합': 8, '삼합': 6, '반합': 4, '방합': 3 };
  const TAEK_POSW = { day: 1, year: 0.6, month: 0.5, hour: 0.4 };
