      if (CHEONEUL[dm].includes(dp.b)) push(6, '천을귀인이 되는 날');
      const cd = CHEONDUK[mb]; if ((cd[0] === 's' && cd[1] === dp.s) || (cd[0] === 'b' && cd[1] === dp.b)) push(5, '천덕일');
      if (WOLDUK(mb) === dp.s) push(5, '월덕일');
      if (ch.gongmang.day.includes(dp.b)) push(-5, '내 일주의 공망 지지가 오는 날');
